'use strict';
const assert=require('node:assert/strict');
const test=require('node:test');
const {validateVehicle,costForStation,rankStations,canBeatKnownBest}=require('./radar-cost');
const v={id:'v1',name:'Citadine',fuel:'Gazole',consumption:6,tankCapacity:50};
const a={id:'A',price:1.70,distanceRoundTripKm:4};
const b={id:'B',price:1.65,distanceRoundTripKm:36};
test('plein de 80 % = 40 litres',()=>assert.equal(costForStation(v,80,a).litersToBuy,40));
test('prix du plein',()=>assert.equal(costForStation(v,80,a).purchaseCost,68));
test('consommation aller-retour',()=>assert.equal(costForStation(v,80,a).travelLiters,0.24));
test('coût total station A',()=>assert.ok(Math.abs(costForStation(v,80,a).totalCost-68.408)<1e-9));
test('coût total station B',()=>assert.ok(Math.abs(costForStation(v,80,b).totalCost-69.564)<1e-9));
test('classement coût total et non prix au litre',()=>assert.deepEqual(rankStations(v,80,[b,a]).map(x=>x.id),['A','B']));
test('petit plein peut changer le classement',()=>assert.equal(rankStations(v,10,[b,a])[0].id,'A'));
test('zéro distance routière',()=>assert.equal(costForStation(v,80,{id:'Z',price:1.7,distanceRoundTripKm:0}).travelCost,0));
test('distance absente => pas de faux coût total',()=>assert.equal(costForStation(v,80,{id:'?',price:1.7}).totalCost,null));
test('distance négative refusée pour le classement',()=>assert.equal(costForStation(v,80,{id:'?',price:1.7,distanceRoundTripKm:-1}).status,'route_unavailable'));
test('distance NaN refusée',()=>assert.equal(costForStation(v,80,{id:'?',price:1.7,distanceRoundTripKm:NaN}).status,'route_unavailable'));
test('distance inconnue en fin de classement',()=>assert.deepEqual(rankStations(v,80,[{id:'?',price:1.5},a]).map(x=>x.id),['A','?']));
test('carburant GPLc accepté',()=>assert.equal(validateVehicle({...v,fuel:'GPLc'}),true));
test('carburant inconnu refusé',()=>assert.throws(()=>validateVehicle({...v,fuel:'GPL'})));
test('réservoir nul refusé',()=>assert.throws(()=>validateVehicle({...v,tankCapacity:0})));
test('consommation négative refusée',()=>assert.throws(()=>validateVehicle({...v,consumption:-1})));
test('pourcentage supérieur à 100 refusé',()=>assert.throws(()=>costForStation(v,101,a)));
test('pourcentage nul refusé',()=>assert.throws(()=>costForStation(v,0,a)));
test('prix invalide refusé',()=>assert.throws(()=>costForStation(v,80,{...a,price:0})));
test('borne inférieure exclut prix impossible',()=>assert.equal(canBeatKnownBest(v,80,2,70),false));
test('borne inférieure conserve prix possible',()=>assert.equal(canBeatKnownBest(v,80,1.6,70),true));
test('pas de mutation des stations',()=>{const stations=[b,a];rankStations(v,80,stations);assert.equal(stations[0],b);});
test('augmentation du plein peut changer le meilleur choix',()=>{const x={id:'X',price:1.75,distanceRoundTripKm:0};const y={id:'Y',price:1.60,distanceRoundTripKm:40};assert.equal(rankStations(v,10,[x,y])[0].id,'X');assert.equal(rankStations(v,100,[x,y])[0].id,'Y');});
